def construct_min_bitwise_array(nums):
    ans = []
    for p in nums:
        if p % 2 == 0:
            # Only 2 is an even prime; x OR (x+1) is always odd, so impossible
            ans.append(-1)
        else:
            low = (p + 1) & -(p + 1)   # 2^t, where t = number of trailing 1s of p
            ans.append(p - (low >> 1))  # clear the highest bit of the trailing run of 1s
    return ans
